      route: [["8:1–4","下山後潔淨痲瘋病人"],["8:5–13","迦百農：百夫長相信一句話的權柄"],["8:14–17","彼得家與黃昏的醫治"],["8:18–27","渡海與平靜風浪"],["8:28–34","加大拉人的地方：群鬼與豬群"]],
      map: mapFor(109, "馬太福音 8:1–34", "從迦百農越過加利利海", "本章先集中在迦百農，隨後由西北岸渡到東岸外邦色彩更濃的地區。海上的風浪與跨岸旅程使耶穌的權柄越過自然、文化和潔淨界線。", ["迦百農","加利利海","加大拉／格拉森地區"], [["④","太 8:5–13","耶穌在迦百農醫治百夫長的僕人。"],["⑥","太 8:23–34","耶穌渡過加利利海，平靜風浪，並在對岸趕出污鬼。"]], "太 8:1–17｜耶穌下山後潔淨痲瘋病人，回到迦百農醫治彼得岳母和許多病人。"),
      timeline: time("權柄越過邊界", "馬太福音 8:1–34", "場景由山下、房屋推向湖面和外邦一側，權柄的範圍不斷擴大。", [["下山","潔淨不潔者","太 8:1–4"],["迦百農","遠距醫治與外邦信心","太 8:5–17"],["海上","斥責風和海","太 8:18–27"],["對岸","勝過群鬼","太 8:28–34"]]),
      illustration: art("https://upload.wikimedia.org/wikipedia/commons/c/c7/JesusCalmingtheTempestDore.jpg", "JesusCalmingtheTempestDore.jpg", "耶穌平靜風浪"),
      background: [["痲瘋與潔淨","聖經所稱大痲瘋涵蓋多種皮膚病；祭司負責確認潔淨。耶穌的觸摸不是被不潔污染，而是使人潔淨。","痲瘋病人被帶回敬拜群體，醫治具有社會與宗教空間的恢復。"],["羅馬百夫長","百夫長通常統領約百名士兵，是帝國軍事秩序的一員；他以自己熟悉的命令結構理解耶穌的權柄。","迦百農靠近區域邊界與交通線，外邦軍事人物在此出現並不突兀。"],["加利利海的突發風暴","湖面低於海平面，四周高地與峽谷可形成突發強風。門徒中雖有漁夫，仍感到必死。","從西北岸到東岸的渡程不是裝飾，而是危險的跨界行動。"]],
      scout: ["耶穌伸手摸不潔者","百夫長相信不需臨場的一句話","8:17 用以賽亞解釋醫治","『狐狸有洞』置於神蹟之間提醒代價","門徒問『這是怎樣的人』成為全章問題"],
      connections: [["以賽亞書 53:4","擔當憂患與痛苦","他誠然擔當我們的憂患，背負我們的痛苦；我們卻以為他受責罰，被神擊打苦待了。"],["詩篇 107:29","平靜風浪的主","他使狂風止息，波浪就平靜。"],["利未記 14:2","潔淨後給祭司察看","長大痲瘋得潔淨的日子，其例乃是這樣：要帶他去見祭司；"]],
      harmony: [["潔淨痲瘋病人","太 8:1–4","可 1:40–45","路 5:12–16","—"],["百夫長僕人","太 8:5–13","—","路 7:1–10","約 4:46–54（相近而有別）"],["平靜風浪","太 8:23–27","可 4:35–41","路 8:22–25","—"],["趕出群鬼","太 8:28–34","可 5:1–20","路 8:26–39","—"]],
      questions: ["三位求助者如何以不同方式靠近耶穌？","百夫長對權柄的理解為何令耶穌希奇？","風浪中門徒的『小信』與跟從有何關係？","城裡的人為何寧願耶穌離開？"]
