    "27": finish(27, {
      title: "十字架、死亡與安葬", passage: "馬太福音 27:1–66", movement: "受難：被定罪的君王、撕裂的幔子與封住的墳墓",
      story: "清晨公會把耶穌交給彼拉多；猶大後悔自盡。群眾選擇巴拉巴，耶穌被戲弄、鞭打、釘十字架。從午正到申初遍地黑暗，耶穌呼喊後斷氣，殿幔撕裂；約瑟把祂葬入新墳，領袖派兵封守。",
      position: "馬太把耶穌稱為猶太人的王，卻讓王冠成為荊棘、寶座成為十字架。天地、聖殿與墳墓都回應祂的死；人的封印反而為復活見證預備舞台。",
      route: [["27:1–10","清晨定案；猶大與三十塊錢"],["27:11–26","彼拉多審問、巴拉巴與洗手"],["27:27–44","兵丁戲弄，古利奈西門背十字架，到各各他"],["27:45–56","黑暗、呼喊、斷氣、幔子撕裂與百夫長認信"],["27:57–66","亞利馬太約瑟安葬；封石看守"]],
      map: mapFor(111, "馬太福音 27:1–66", "受審、出城與墳墓", "耶穌由大祭司處被送往彼拉多衙門，再被帶出城到各各他；墳墓在刑場附近。古城內精確位置有學術討論，地圖路線應按傳統與文本相互參照。", ["公會／大祭司處","彼拉多衙門","各各他","園中新墳"], [["⑤","太 27:1","清晨公會正式定案，要把耶穌治死。"],["⑥","太 27:2–31","耶穌被解往巡撫彼拉多前受審、鞭打和戲弄。"],["⑧","太 27:32–60","耶穌被帶到各各他釘十字架；死後由亞利馬太約瑟安葬在新墳裡。"]], "太 27:15–31｜彼拉多釋放巴拉巴，把耶穌交給兵丁；太 27:61–66｜婦女看見墳墓，領袖次日要求封石看守。"),
      timeline: time("受難日：由清晨判決到安息日前安葬", "馬太福音 27:1–66", "審判、戲弄、十字架、死亡與匆促安葬依一天的光線推進。", [["清晨","公會定案並交彼拉多","太 27:1–26"],["上午","戲弄並往各各他","太 27:27–44"],["午正至申初","遍地黑暗，耶穌斷氣","太 27:45–56"],["傍晚至次日","安葬、封石、看守","太 27:57–66"]]),
      illustration: art("https://upload.wikimedia.org/wikipedia/commons/2/26/Crucifixiondarkness.jpg", "Crucifixiondarkness.jpg", "十字架時遍地黑暗"),
      background: [["羅馬與公會的審判","公會以宗教罪名審問，交彼拉多時則以王權威脅進入羅馬司法。彼拉多洗手不能解除其交付無辜者的責任。","衙門、城門與刑場構成由政治中心到城外羞辱之路。"],["十字架刑罰","釘十字架是羅馬公開、漫長、羞辱性的死刑，常用於奴隸與反叛者；『猶太人的王』牌子同時是罪名和真理。","刑場位於城外交通可見處，以死亡身體警告往來者。"],["殿幔撕裂與新墳","幔子由上到下撕裂象徵神主動打開新的親近；富人約瑟的新墳、巨石與看守則強調死亡和埋葬的真實。","聖殿與城外墳墓在地圖上分開，在神學上卻由耶穌之死連結。"]],
      scout: ["猶大承認流無辜之血，領袖卻把錢與責任切割","群眾選擇名字也含『耶穌』的巴拉巴，拒絕真正救主","戲弄中的袍、冠冕與跪拜反諷地宣告王權","詩篇 22 的語言遍布十字架敘事","百夫長與看守者成為說『真是神的兒子』的人"],
      connections: [["詩篇 22:1、7–8","十字架呼喊與嗤笑","（大衛的詩，交與伶長。調用朝鹿。）我的神，我的神！為甚麼離棄我？為甚麼遠離不救我？不聽我唉哼的言語？凡看見我的都嗤笑我；他們撇嘴搖頭，說：他把自己交託耶和華，耶和華可以救他罷！耶和華既喜悅他，可以搭救他罷！"],["以賽亞書 53:9","與財主同葬","他雖然未行強暴，口中也沒有詭詐，人還使他與惡人同埋；誰知死的時候與財主同葬。"],["阿摩司書 8:9","午間黑暗","主耶和華說：到那日，我必使日頭在午間落下，使地在白晝黑暗。"]],
      harmony: [["彼拉多審判","太 27:11–31","可 15:1–20","路 23:1–25","約 18:28–19:16"],["釘十字架與死亡","太 27:32–56","可 15:21–41","路 23:26–49","約 19:17–37"],["安葬","太 27:57–61","可 15:42–47","路 23:50–56","約 19:38–42"],["封石看守","太 27:62–66","—","—","—"]],
      questions: ["彼拉多洗手與猶大退錢為何都不能代替悔改？","馬太如何用兵丁戲弄反諷地宣告耶穌為王？","幔子撕裂、地震與聖徒復起共同指向甚麼？","婦女、約瑟、百夫長分別在黑暗中作了甚麼見證？"]
    }),
